  1005|function buildStageBar(containerId, stages, counts, total) {
  1006|  const el = document.getElementById(containerId);
  1007|  if(total===0) { el.innerHTML = '<div style="background:#334155;width:100%;height:8px;border-radius:4px;"></div>'; return; }
  1008|  const colors = ['#64748b','#3b82f6','#8b5cf6','#06b6d4','#f59e0b','#f97316','#22c55e','#14b8a6'];
  1009|  let html = '';
  1010|  stages.forEach((s,i) => {
  1011|    const pct = (counts[i]||0)/total*100;
  1012|    if(pct>0) html += `<div class="seg" style="width:${pct}%;background:${colors[i]||'#64748b'};\"></div>`;
  1013|  });
  1014|  el.innerHTML = html || '<div style="background:#334155;width:100%;height:8px;border-radius:4px;"></div>';
