  1017|function calcStats() {
  1018|  const saasLeads = saasPipeline.leads;
  1019|  const consultLeads = consultingPipeline.leads;
  1020|  const booksLeads = booksPipeline.leads;
  1021|
  1022|  const saasTotal = saasLeads.length;
  1023|  const consultTotal = consultLeads.length;
  1024|  const booksTotal = booksLeads.length;
  1025|
  1026|  // Projected revenue: SaaS annual subscription, Consulting deal value, Books pipeline value
  1027|  const saasRevenue = saasTotal * 199 * 12;
  1028|  const consultRevenue = consultTotal * 199;
  1029|  const booksRevenue = booksLeads.reduce((s,r) => s + r.value, 0);
  1030|
  1031|  const totalLeads = saasTotal + consultTotal + booksTotal;
  1032|  const totalRevenue = saasRevenue + consultRevenue + booksRevenue;
  1033|  const convRate = 2.8;
  1034|
  1035|  // Stale lead counts (>7 days in same stage)
  1036|  const saasStale = saasLeads.filter(l => l.daysInStage > 7).length;
  1037|  const consultStale = consultLeads.filter(l => l.daysInStage > 7).length;
  1038|  const booksStale = booksLeads.filter(l => l.daysInStage > 7).length;
  1039|  const totalStale = saasStale + consultStale + booksStale;
  1040|
  1041|  document.getElementById('totalLeads').textContent = totalLeads;
  1042|  document.getElementById('totalRevenue').textContent = '$' + totalRevenue.toLocaleString();
  1043|  document.getElementById('staleCount').textContent = totalStale;
  1044|
  1045|  document.getElementById('saasCount').textContent = saasTotal;
  1046|  document.getElementById('saasRevenue').textContent = '$' + saasRevenue.toLocaleString();
  1047|  document.getElementById('saasStaleCount').textContent = saasStale;
