      --success: #22c55e;
      --warning: #f59e0b;
      --danger: #ef4444;
      --orange: #f97316;
      --info: #06b6d4;
      --purple: #8b5cf6;
      --sidebar-w: 220px;
      --shadow: 0 4px 24px rgba(0,0,0,0.3);
    }
    html { scroll-behavior: smooth; }
