      : `<div class="book-series" style="color:var(--text-secondary);">${b.series}</div>`;
    return `<div class="book-card">
      ${seriesBadge}
      <div class="book-title">${b.title}</div>
      <div class="book-meta">
        ${statusBadge(b.status)}
      </div>
    </div>`;
  }).join('');
}

function renderSaaS() {
  const grid = document.getElementById('saasGrid');
