    return `<div class="saas-card">
      <div class="saas-name">${a.name}${websiteTag}</div>
      <div class="saas-gh-name">${a.isWebsite ? 'mifeco.com' : a.ghName}</div>
      <div class="saas-links">
        <a href="${a.github}" target="_blank" class="saas-link">
          <span class="link-icon">🐙</span>
          <span class="link-label">GitHub:</span>
          <span class="link-url">${a.github}</span>
        </a>
        <a href="${a.prodUrl}" target="_blank" class="saas-link">
          <span class="link-icon">🚀</span>
          <span class="link-label">Production:</span>
          <span class="link-url">${a.prodUrl}</span>
